1	package ociresources
2	
3	import (
4		"log"
5		"strings"
6	
7		tea "charm.land/bubbletea/v2"
8		"charm.land/lipgloss/v2"
9	
10		"github.com/anthnel/devdesk/internal/imagesearch"
11		"github.com/anthnel/devdesk/internal/jobs"
12		"github.com/anthnel/devdesk/internal/ui/datatable"
13		"github.com/anthnel/devdesk/internal/ui/indicator"
14		"github.com/anthnel/devdesk/internal/ui/theme"
15	)
16	
17	// searchRow is one line of the level 1 table: an image, and the label of the
18	// registry that returned it.
19	type searchRow struct {
20		img   imagesearch.Image
21		label string
22	}
23	
24	// searchColumns describes the level 1 table. Minimal for now: the full screen
25	// (Stars, Official, Description) comes later.
26	func searchColumns() []datatable.Column[searchRow] {
27		return []datatable.Column[searchRow]{
28			datatable.IndicatorColumn(
29				func(searchRow) indicator.State { return indicator.Idle },
30				func(searchRow) string { return theme.IconDocker },
31				func(searchRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
32			),
33			{
34				Title: "Name", Sizing: datatable.SizingContent, MinWidth: 24, Flex: 1,
35				Cell:   func(r searchRow) string { return r.img.Name },
36				Search: func(r searchRow) string { return r.img.Name },
37			},
38			{
39				Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 16,
40				Cell: func(r searchRow) string { return r.label },
41			},
42		}
43	}
44	
45	// newSearchTable builds the level 1 table, in arrival order (no sort).
46	func newSearchTable() *datatable.Model[searchRow] {
47		t := datatable.New(datatable.Config[searchRow]{
48			Columns:    searchColumns(),
49			SortColumn: -1,
50		})
51		return &t
52	}
53	
54	// rebuildSearchTable hands the collected images to the table.
55	func (b *RegistryBrowser) rebuildSearchTable() {
56		rows := make([]searchRow, len(b.images))
57		for i, img := range b.images {
58			label := ""
59			if e := b.entryFor(img.EntryKey); e != nil {
60				label = e.Alias
61				if label == "" {
62					label = e.URL
63				}
64			}
65			rows[i] = searchRow{img: img, label: label}
66		}
67		b.searchTable.SetItems(rows)
68		b.searchTable.Resize(b.width+2, max(b.height, 1))
69	}
70	
71	// AddImageResults takes one registry's answer. It returns false, touching
72	// nothing, when the answer belongs to another lot. pendingSearches never goes
73	// below zero.
74	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
75		if msg.Gen != b.gen {
76			return false
77		}
78		if b.pendingSearches > 0 {
79			b.pendingSearches--
80		}
81		if msg.Err == nil {
82			for _, img := range msg.Images {
83				img.EntryKey = msg.EntryKey
84				b.images = append(b.images, img)
85			}
86		}
87		b.rebuildSearchTable()
88		return true
89	}
90	
91	// handleImagesKeyMsg handles the keys of the level 1 table. esc goes back to
92	// the form and drops the lot: its late answers are no longer wanted.
93	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
94		if msg.String() == "esc" {
95			b.cancelInFlight()
96			b.gen = nextBrowserGen()
97			b.pendingSearches = 0
98			b.state = browserStateInput
99			b.searchTable.Blur()
100			b.updateFocus()
101			return b, nil
102		}
103		return b, b.searchTable.Update(msg)
104	}
105	
106	// handleImageSearchResult records one registry's answer; a stale one is ignored.
107	func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
108		if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
109			return m, nil
110		}
111		if msg.Err != nil {
112			alias := msg.EntryKey
113			if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
114				alias = entryAlias(*e)
115			}
116			log.Printf("ERROR [oci_resources] image search on %s: %s", alias, jobs.SafeCause(msg.Err))
117		}
118		return m, nil
119	}
120	
121	// handleRegistryBrowserWarn shows the browser's warning in the footer.
122	func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
123		return m, m.footer.Warn(strings.TrimSpace(msg.Text))
124	}
