18	// Level 1 of the image search on screen (DEVDESK-395, IS-01 c.7 and c.8): the
19	// header count, the shortcuts, the help, the filter bar, esc, the loading
20	// state in the footer (Rules 114, 125, 128, 130, 139) and enter doing nothing.
21	
22	// searchingModel opens the browser at level 1 with both registries still
23	// pending: the lot is started, no answer has come back yet.
24	func lvl1SearchingModel(t *testing.T) Model {
25		t.Helper()
26		withImageSearcher(t, &fakeSearcher{})
27		m, cmd := submitRaw(t, browsingModel(t), "nginx")
28		if cmd == nil {
29			t.Fatal("the search started nothing")
30		}
31		if m.registryBrowser.state != browserStateImages {
32			t.Fatalf("state = %d, want browserStateImages", m.registryBrowser.state)
33		}
34		if m.registryBrowser.pendingSearches != 2 {
35			t.Fatalf("pendingSearches = %d, want 2", m.registryBrowser.pendingSearches)
36		}
37		return m
38	}
