239	// c.7, c.8, Rules 130 and 137: the shortcuts of level 1.
240	func TestLevelOneShortcuts(t *testing.T) {
241		m := lvl1ImagesModel(t)
242		sc := m.GetShortcuts()
243		for _, key := range []string{"/", "esc"} {
244			if !testutil.HasShortcut(sc, key) {
245				t.Errorf("level 1 lacks the %q shortcut", key)
246			}
247			if testutil.HasShortcut(sc, key) && !testutil.ShortcutEnabled(sc, key) {
248				t.Errorf("%q is greyed at level 1", key)
249			}
250		}
251		for _, key := range []string{"enter", ".", "→", "r"} {
252			if testutil.HasShortcut(sc, key) {
253				t.Errorf("level 1 advertises %q", key)
254			}
255		}
256	
257		m = feed(t, m, testutil.Key("/"))
