264	// Rule 130: the set of keys does not depend on whether there are rows.
265	func TestLevelOneShortcutKeysDoNotDependOnTheRows(t *testing.T) {
266		empty := lvl1SearchingModel(t)
267		filled := lvl1ImagesModel(t)
268		a := testutil.ShortcutKeys(empty.GetShortcuts())
269		b := testutil.ShortcutKeys(filled.GetShortcuts())
270		if !slices.Equal(a, b) {
271			t.Errorf("keys without rows = %v, with rows = %v", a, b)
272		}
