275	// Level 2 keeps its enter.
276	func TestLevelTwoEnterIsStillThere(t *testing.T) {
277		m := resultsModel(t)
278		var found shortcut.Shortcut
279		for _, s := range m.GetShortcuts() {
280			if s.Key == "enter" {
281				found = s
282			}
283		}
284		if found.Description != "View CVE details" {
285			t.Errorf("level 2 enter = %q, want View CVE details", found.Description)
286		}
287	}
288	
289	// Rule 114: the help lists the keys of level 1 and the activity legend.
290	func TestLevelOneHelpListsItsKeysAndTheLegend(t *testing.T) {
291		c := lvl1ImagesModel(t).GetHelpContent()
292		keys := map[string]bool{}
293		for _, kb := range c.KeyBindings {
294			keys[kb.Key] = true
295		}
296		for _, want := range []string{"/ (Browser images)", "esc (Browser images)"} {
297			if !keys[want] {
298				t.Errorf("help lacks the %q binding", want)
299			}
300		}
301		if keys["enter (Browser images)"] {
302			t.Error("help documents an enter at level 1, which does nothing")
303		}
304		if !lvl1HasSection(c, indicator.Legend().Title) {
305			t.Errorf("help lacks the %q section", indicator.Legend().Title)
306		}
307		if !lvl1HasSection(c, "Registry Browser") {
308			t.Error(`help lacks a "Registry Browser" section`)
309		}
